// =====================================================================
//  PARAMÈTRES À ADAPTER — c'est le seul endroit à modifier
// =====================================================================
const config = {
  // true  = TOUS les emails partent vers email_test (aucun prospect contacté)
  // false = envoi réel aux prospects
  mode_test: true,
  email_test: 'votre.adresse@exemple.fr',

  // Google Sheet de suivi (l'ID est dans l'URL : docs.google.com/spreadsheets/d/<ID>/edit)
  google_sheet_id: 'REMPLACER_PAR_ID_DU_GOOGLE_SHEET',

  // Expéditeur / signature
  expediteur_email: 'votre.adresse@exemple.fr',
  expediteur_nom: 'Prénom NOM',
  expediteur_activite: 'Votre métier — Votre entreprise',
  expediteur_telephone: '06 00 00 00 00',

  // Réunion
  nom_groupe: 'BNI Tout Business',
  lieu_reunion: 'Palais des Congrès de Perpignan',
  heure_reunion: '7h00',

  // Zone de recherche
  ville: 'Perpignan',
  centre_lat: 42.6986,
  centre_lng: 2.8954,
  rayon_km: 10,

  // Volumes
  max_emails_par_semaine: 10,   // emails envoyés au maximum par exécution
  max_metiers_par_semaine: 5,   // métiers recherchés par exécution (rotation)
  candidats_par_metier: 4,      // entreprises analysées par métier

  // Ciblage TPE / micro-entreprises
  max_avis_google: 150,         // au-delà : probablement une grosse structure / chaîne
  tranches_effectif_ok: ['NN', '00', '01', '02', '03'], // 0 à 9 salariés (codes INSEE)
  garder_si_effectif_inconnu: true,
};

// Date de la prochaine réunion (prochain mercredi)
const d = new Date();
const delta = ((3 - d.getDay() + 7) % 7) || 7;
d.setDate(d.getDate() + delta);
config.date_reunion = d.toLocaleDateString('fr-FR', {
  weekday: 'long', day: 'numeric', month: 'long', timeZone: 'Europe/Paris',
});
config.aujourdhui = new Date().toISOString().slice(0, 10);

return [{ json: config }];

// Métiers non représentés dans le groupe, les moins récemment recherchés en premier
const cfg = $('Config').first().json;
const norm = (s) => String(s ?? '').trim().toUpperCase();

const aChercher = $input.all()
  .map((i) => i.json)
  .filter((r) => r.metier && norm(r.statut) === 'A_RECHERCHER');

aChercher.sort((a, b) =>
  String(a.derniere_recherche ?? '').localeCompare(String(b.derniere_recherche ?? '')));

return aChercher.slice(0, cfg.max_metiers_par_semaine).map((r) => ({
  json: {
    metier: String(r.metier).trim(),
    requete: String(r.requete_maps || r.metier).trim(),
  },
}));

const cfg = $('Config').first().json;
return $input.all().map((i) => ({
  json: { metier: i.json.metier, derniere_recherche: cfg.aujourdhui },
}));

