// Aplatit les résultats Maps, filtre (distance, taille, doublons) et limite par métier
const cfg = $('Config').first().json;
const metiers = $('Choisir les métiers').all();
const reponses = $input.all();

const DOMAINES_GENERIQUES = ['facebook.com', 'instagram.com', 'linktr.ee', 'google.com',
  'business.site', 'pagesjaunes.fr', 'linkedin.com', 'wixsite.com', 'jimdosite.com'];
const tel = (s) => String(s ?? '').replace(/\D/g, '').replace(/^33/, '0');
const domaine = (u) => {
  try { return new URL(u).hostname.replace(/^www\./, '').toLowerCase(); } catch (e) { return ''; }
};
const generique = (d) => DOMAINES_GENERIQUES.some((g) => d === g || d.endsWith('.' + g));
const distanceKm = (lat1, lng1, lat2, lng2) => {
  const r = (x) => (x * Math.PI) / 180;
  const a = Math.sin(r(lat2 - lat1) / 2) ** 2 +
    Math.cos(r(lat1)) * Math.cos(r(lat2)) * Math.sin(r(lng2 - lng1) / 2) ** 2;
  return 6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
};

// Déjà contactés (les lignes TEST ne comptent pas)
const vus = { place: new Set(), tel: new Set(), dom: new Set() };
for (const i of $('Lire Prospects').all()) {
  const r = i.json;
  if (String(r.statut ?? '').toUpperCase() === 'TEST') continue;
  if (r.place_id) vus.place.add(String(r.place_id));
  if (tel(r.telephone)) vus.tel.add(tel(r.telephone));
  const d = domaine(r.site_web);
  if (d && !generique(d)) vus.dom.add(d);
}

const out = [];
reponses.forEach((rep, idx) => {
  const metier = metiers[idx]?.json.metier;
  let gardes = 0;
  for (const p of rep.json.places ?? []) {
    if (gardes >= cfg.candidats_par_metier) break;
    if (p.businessStatus && p.businessStatus !== 'OPERATIONAL') continue;
    if ((p.userRatingCount ?? 0) > cfg.max_avis_google) continue;
    if (!p.websiteUri && !p.nationalPhoneNumber) continue;

    const dist = p.location
      ? distanceKm(cfg.centre_lat, cfg.centre_lng, p.location.latitude, p.location.longitude)
      : 999;
    if (dist > cfg.rayon_km) continue;

    const t = tel(p.nationalPhoneNumber);
    const d = domaine(p.websiteUri);
    if (vus.place.has(p.id) || (t && vus.tel.has(t)) || (d && !generique(d) && vus.dom.has(d))) continue;
    vus.place.add(p.id);
    if (t) vus.tel.add(t);
    if (d && !generique(d)) vus.dom.add(d);

    let urlMentions = '';
    try { if (p.websiteUri && !generique(d)) urlMentions = new URL(p.websiteUri).origin + '/mentions-legales'; } catch (e) {}

    out.push({ json: {
      metier,
      entreprise: p.displayName?.text ?? '',
      adresse: p.formattedAddress ?? '',
      code_postal: (String(p.formattedAddress ?? '').match(/\b(\d{5})\b/) || [])[1] ?? '',
      telephone: p.nationalPhoneNumber ?? '',
      site_web: p.websiteUri ?? '',
      site_exploitable: Boolean(p.websiteUri) && !generique(d),
      url_mentions: urlMentions,
      distance_km: Math.round(dist * 10) / 10,
      note_google: p.rating ?? '',
      nb_avis: p.userRatingCount ?? 0,
      place_id: p.id,
      lien_maps: p.googleMapsUri ?? '',
    } });
    gardes++;
  }
});
return out;

// Extrait le meilleur email trouvé sur la page d'accueil + mentions légales
const cands = $('Filtrer candidats').all();
const accueil = $('Site - accueil').all();
const mentions = $input.all();

const dejaContactes = new Set(
  $('Lire Prospects').all()
    .filter((i) => String(i.json.statut ?? '').toUpperCase() !== 'TEST')
    .map((i) => String(i.json.email ?? '').toLowerCase().trim())
    .filter(Boolean),
);

const BLOQUES = /(example\.|exemple\.|sentry|wixpress|domain\.|email\.com|votre|your|nom@|name@|test@|noreply|no-reply|ne-pas-repondre|\.(png|jpe?g|gif|webp|svg|css|js)$)/i;
const HEBERGEURS = ['ovh.com', 'ovh.net', 'ovhcloud.com', 'o2switch.fr', 'ionos.fr', 'ionos.com', '1and1.fr',
  'hostinger.com', 'gandi.net', 'wix.com', 'squarespace.com', 'google.com', 'amazon.com',
  'cloudflare.com', 'planethoster.info', 'lws.fr', 'infomaniak.com', 'shopify.com', 'cnil.fr',
  'jimdo.com', 'godaddy.com', 'webflow.com'];
const PERSO = ['gmail.com', 'orange.fr', 'wanadoo.fr', 'free.fr', 'hotmail.fr', 'hotmail.com',
  'outlook.fr', 'outlook.com', 'sfr.fr', 'laposte.net', 'yahoo.fr', 'icloud.com', 'live.fr'];

const texte = (it) => (typeof it?.json?.data === 'string' ? it.json.data : '');
const nettoie = (s) => s
  .replace(/&#64;|&#x40;|\s*\[\s*at\s*\]\s*|\s*\(\s*at\s*\)\s*|%40/gi, '@')
  .replace(/\s*\[\s*(dot|point)\s*\]\s*|\s*\(\s*(dot|point)\s*\)\s*/gi, '.');
const domaine = (u) => {
  try { return new URL(u).hostname.replace(/^www\./, '').toLowerCase(); } catch (e) { return ''; }
};

return cands.map((c, i) => {
  const html = nettoie(texte(accueil[i]) + ' ' + texte(mentions[i]));
  const trouves = [...new Set((html.match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi) ?? [])
    .map((e) => e.toLowerCase().replace(/^u003e/, '')))]
    .filter((e) => !BLOQUES.test(e))
    .filter((e) => !HEBERGEURS.some((h) => e.endsWith('@' + h) || e.endsWith('.' + h)));

  const dom = domaine(c.json.site_web);
  const score = (e) => {
    const d = e.split('@')[1];
    let s = 0;
    if (dom && (d === dom || d.endsWith('.' + dom))) s += 10;
    else if (PERSO.includes(d)) s += 5;
    if (/^(contact|info|bonjour|hello)@/.test(e)) s += 2;
    return s;
  };
  trouves.sort((a, b) => score(b) - score(a));

  const email = trouves.find((e) => !dejaContactes.has(e)) ?? '';
  const deja = !email && trouves.length > 0;
  return { json: { ...c.json, email, email_deja_contacte: deja } };
}).filter((i) => !i.json.email_deja_contacte);

// Ajoute le représentant légal (API Recherche d'entreprises), filtre les TPE,
// puis répartit : 'email' (max N, réparti entre métiers) ou 'appel' (pas d'email trouvé)
const cfg = $('Config').first().json;
const base = $('Extraire email').all();
const reps = $input.all();

const capitalise = (s) => String(s ?? '').toLowerCase()
  .replace(/(^|[\s'-])(\p{L})/gu, (m, sep, l) => sep + l.toUpperCase());

const enrichis = [];
base.forEach((b, i) => {
  const r = reps[i]?.json?.results?.[0];
  let dirigeant = '', qualite = '', siren = '', effectif = '', nom_legal = '';
  if (r) {
    if (r.etat_administratif === 'C') return;                       // entreprise cessée
    if (['GE', 'ETI'].includes(r.categorie_entreprise)) return;      // trop grosse
    siren = r.siren ?? '';
    effectif = r.tranche_effectif_salarie ?? '';
    nom_legal = r.nom_complet ?? '';
    const pp = (r.dirigeants ?? []).find((x) => x.type_dirigeant === 'personne physique');
    if (pp) {
      const prenom = String(pp.prenoms ?? '').split(/[\s,]+/)[0];
      dirigeant = [capitalise(prenom), String(pp.nom ?? '').toUpperCase()].filter(Boolean).join(' ');
      qualite = pp.qualite ?? '';
    } else if (r.nature_juridique === '1000') {                       // entrepreneur individuel
      dirigeant = capitalise(nom_legal.split('(')[0].trim());
      qualite = 'Entrepreneur individuel';
    }
  }
  if (effectif && !cfg.tranches_effectif_ok.includes(effectif)) return;
  if (!effectif && !cfg.garder_si_effectif_inconnu) return;
  enrichis.push({ ...b.json, dirigeant, qualite_dirigeant: qualite, siren, effectif, nom_legal });
});

// Répartition équitable entre métiers (round-robin) dans la limite hebdo
const parMetier = {};
for (const e of enrichis.filter((e) => e.email)) (parMetier[e.metier] ??= []).push(e);
const files = Object.values(parMetier);
const emails = [];
while (emails.length < cfg.max_emails_par_semaine && files.some((f) => f.length)) {
  for (const f of files) {
    if (f.length && emails.length < cfg.max_emails_par_semaine) emails.push(f.shift());
  }
}

const appels = enrichis.filter((e) => !e.email && e.telephone);
return [
  ...emails.map((e) => ({ json: { ...e, canal: 'email' } })),
  ...appels.map((e) => ({ json: { ...e, canal: 'appel' } })),
];

// Construit la requête Claude pour chaque prospect
const cfg = $('Config').first().json;

const system = `Tu rédiges, au nom de ${cfg.expediteur_nom} (${cfg.expediteur_activite}), membre du club d'affaires ${cfg.nom_groupe} à ${cfg.ville}, un email court d'invitation adressé au dirigeant d'une petite entreprise locale.

Objectif : l'inviter à venir découvrir le groupe en tant que visiteur lors d'une réunion, sans engagement.

Faits à utiliser (n'invente rien d'autre) :
- Le groupe se réunit chaque mercredi à ${cfg.heure_reunion} au ${cfg.lieu_reunion}, autour d'un petit-déjeuner.
- Prochaine réunion : ${cfg.date_reunion}.
- Le principe BNI : des entrepreneurs locaux qui se recommandent mutuellement des affaires ; une seule personne par métier dans le groupe.
- Le métier du destinataire n'est pas encore représenté dans le groupe : c'est précisément pour cela qu'on le contacte.

Consignes :
- Français, vouvoiement, ton chaleureux, direct et professionnel ; pas de superlatifs ni de formules commerciales creuses.
- 90 à 150 mots, 3 ou 4 courts paragraphes séparés par une ligne vide, texte brut (pas de markdown, pas de liste).
- Commence par "Bonjour" suivi du prénom et du nom du dirigeant s'il est connu, sinon "Bonjour,".
- Mentionne le nom de l'entreprise et son métier de façon naturelle ; tu peux évoquer un élément concret fourni (note Google, quartier/commune) s'il est pertinent.
- Termine par une invitation claire : répondre à cet email ou appeler pour réserver sa place de visiteur.
- N'écris PAS de signature ni de formule de fin avec un nom : elle est ajoutée automatiquement. Une formule comme "Au plaisir de vous y accueillir," en dernière ligne est permise.
- Objet : court (moins de 70 caractères), personnalisé, sans majuscules abusives ni emoji.`;

return $input.all().map((i) => {
  const p = i.json;
  const fiche = {
    entreprise: p.entreprise,
    metier: p.metier,
    dirigeant: p.dirigeant || null,
    commune: (String(p.adresse).match(/\d{5}\s+([^,]+)/) || [])[1] || cfg.ville,
    note_google: p.note_google || null,
    nb_avis_google: p.nb_avis || null,
  };
  const claude_body = {
    model: 'claude-opus-5-5',
    max_tokens: 4000,
    output_config: {
      effort: 'low',
      format: {
        type: 'json_schema',
        schema: {
          type: 'object',
          properties: { objet: { type: 'string' }, corps: { type: 'string' } },
          required: ['objet', 'corps'],
          additionalProperties: false,
        },
      },
    },
    fallbacks: 'default',
    system,
    messages: [{ role: 'user', content: 'Rédige l\'email pour ce prospect :\n' + JSON.stringify(fiche, null, 2) }],
  };
  return { json: { ...p, claude_body } };
});

// Assemble l'email final (texte + HTML + signature + mention de désinscription)
const cfg = $('Config').first().json;
const prospects = $('Préparer prompt').all();
const reponses = $input.all();

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return prospects.map((p, i) => {
  const { claude_body, ...prospect } = p.json;
  const r = reponses[i]?.json ?? {};
  let mail = null;
  if (r.stop_reason !== 'refusal') {
    const txt = (r.content ?? []).filter((b) => b.type === 'text').map((b) => b.text).join('');
    try { mail = JSON.parse(txt); } catch (e) { mail = null; }
  }
  const genere = Boolean(mail?.objet && mail?.corps);
  if (!genere) {
    // Modèle de secours si l'IA ne répond pas
    mail = {
      objet: `Invitation ${cfg.nom_groupe} — nous cherchons un(e) ${prospect.metier}`,
      corps: `Bonjour${prospect.dirigeant ? ' ' + prospect.dirigeant : ''},\n\n` +
        `Je fais partie du ${cfg.nom_groupe}, un groupe d'entrepreneurs de ${cfg.ville} qui se recommandent mutuellement des clients. ` +
        `Chaque métier n'y est représenté qu'une seule fois, et nous n'avons pas encore de ${prospect.metier}.\n\n` +
        `Je serais ravi(e) de vous accueillir en tant que visiteur, sans engagement, lors de notre prochaine réunion : ` +
        `${cfg.date_reunion} à ${cfg.heure_reunion} au ${cfg.lieu_reunion}, autour d'un petit-déjeuner.\n\n` +
        `Il vous suffit de répondre à cet email ou de m'appeler pour réserver votre place.\n\nAu plaisir de vous y accueillir,`,
    };
  }

  const signature = `${cfg.expediteur_nom}\n${cfg.expediteur_activite}\nMembre du ${cfg.nom_groupe}\n${cfg.expediteur_telephone}`;
  const mention = `Vous recevez ce message car votre activité correspond à un métier recherché par notre groupe. ` +
    `Pour ne plus être contacté(e), répondez simplement « STOP ».`;

  const texte = `${mail.corps.trim()}\n\n${signature}\n\n--\n${mention}`;
  const html =
    mail.corps.trim().split(/\n\s*\n/).map((para) => `<p>${esc(para).replace(/\n/g, '<br>')}</p>`).join('') +
    `<p>${esc(signature).replace(/\n/g, '<br>')}</p>` +
    `<p style="color:#888;font-size:12px">${esc(mention)}</p>`;

  return { json: {
    ...prospect,
    destinataire: cfg.mode_test ? cfg.email_test : prospect.email,
    objet_email: cfg.mode_test ? `[TEST → ${prospect.email}] ${mail.objet}` : mail.objet,
    texte, html,
    redige_par_ia: genere,
  } };
});

const cfg = $('Config').first().json;
const emails = $("Préparer l'email").all();
const envois = $input.all();
const maintenant = new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' });

return emails.map((e, i) => {
  const p = e.json;
  const erreur = envois[i]?.json?.error;
  return { json: {
    date: maintenant,
    metier: p.metier,
    entreprise: p.entreprise,
    dirigeant: p.dirigeant,
    qualite_dirigeant: p.qualite_dirigeant,
    email: p.email,
    telephone: p.telephone,
    site_web: p.site_web,
    adresse: p.adresse,
    distance_km: p.distance_km,
    note_google: p.note_google,
    nb_avis: p.nb_avis,
    siren: p.siren,
    effectif: p.effectif,
    place_id: p.place_id,
    lien_maps: p.lien_maps,
    objet_email: p.objet_email,
    statut: erreur ? 'ERREUR_ENVOI' : (cfg.mode_test ? 'TEST' : 'ENVOYE'),
    commentaire: erreur ? String(erreur.message ?? erreur).slice(0, 200) : (p.redige_par_ia ? '' : 'modèle de secours'),
  } };
});
